import pytest
from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/test")
async def test_endpoint(q: Optional[int] = Form(None)):
    return {"q": q}

client = TestClient(app)

def test_empty_string_as_none():
    # When q is sent as an empty string, it should be interpreted as None 
    # if the default is None and it's an Optional[int].
    # Before the fix, this might send "" to Pydantic validation for int, which fails.
    response = client.post("/test", data={"q": ""})
    assert response.status_code == 200
    assert response.json() == {"q": None}

def test_value_provided():
    response = client.post("/test", data={"q": "123"})
    assert response.status_code == 200
    assert response.json() == {"q": 123}

def test_value_missing():
    response = client.post("/test")
    assert response.status_code == 200
    assert response.json() == {"q": None}

if __name__ == "__main__":
    try:
        test_empty_string_as_none()
        test_value_provided()
        test_value_missing()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

